mapper.select:
SELECT *
FROM shopion.tOrdOrderProdApprovLine

    AND OrderNo = #{orderNo}
    AND OrderProdNo = #{orderProdNo}

ORDER BY ApprovLevel ASC

SELECT COUNT(*)
FROM shopion.tOrdOrderProdApprovLine

    AND OrderNo = #{orderNo}
    AND OrderProdNo = #{orderProdNo}

SELECT COUNT(*)
FROM shopion.tOrdOrderProdApprovLine
WHERE ApprovResult IS NULL
AND OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}

SELECT COUNT(*)
FROM shopion.tOrdOrderProdApprovLine
WHERE ApprovResult = 'A'
AND OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}

SELECT COUNT(*)
FROM shopion.tOrdOrderProdApprovLine
WHERE ApprovResult = 'R'
AND OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}

mapper.update:
UPDATE shopion.tOrdOrderProdApprovLine SET
    ApprovResult = 'A', ApprovDate = NOW(), ApprovMemo = #{approvMemo},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND ApprovCustId = #{approvCustId}

UPDATE shopion.tOrdOrderProdApprovLine SET
    ApprovResult = 'R', ApprovDate = NOW(), ApprovMemo = #{approvMemo},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND ApprovCustId = #{approvCustId}

mapper.delete:
DELETE FROM shopion.tOrdOrderProdApprovLine
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND ApprovLevel = #{approvLevel}
